import Foundation
import SwiftUI

struct BrandConfig {
    static let name = "Austrian.rocks"
    static let slug = "austrian-rocks"

    struct Brand {
        // Brand color - currently using the existing AppGreen color
        // Update these values to change the app's brand color
        static let color = Color("AppGreen")

        // Alternative: Define custom color directly
        // static let color = Color(red: 0.396, green: 0.769, blue: 0.400)
    }

    struct Domains {
        static let main = "austrian.rocks"
        static let www = "www.austrian.rocks"
        static let assets = "assets.austrian.rocks"
    }

    struct Contact {
        static let email = "hello@austrian.rocks"
    }

    struct AppStore {
        // Intentionally absent until App Store release; setting this enables the rate/review link.
        static let appID: String? = nil

        static var reviewURL: URL? {
            guard let appID, !appID.isEmpty else { return nil }
            return URL(string: "https://itunes.apple.com/app/id\(appID)?action=write-review")
        }
    }

    struct Mapbox {
        static let account = "dgtlntv"
        static let styleID = "cmi0wnif6004t01r0araj0ts0"
        // TODO: create a dedicated dark-mode style; for now, fall back to the light style.
        static let darkStyleID = styleID
        static let problemsTilesetID = "95ifk802"
        static let problemsSourceLayer = "problems_8-85f5eq"

        static var styleURL: String {
            "mapbox://styles/\(account)/\(styleID)"
        }

        static var darkStyleURL: String {
            "mapbox://styles/\(account)/\(darkStyleID)"
        }

        static var problemsTilesetURL: String {
            "mapbox://\(account).\(problemsTilesetID)"
        }
    }

    struct Database {
        static let filename = "austrian-rocks"
    }
}

//
//  DiscoverView.swift
//  Austrian.rocks
//
//  Created by Nicolas Mondollot on 27/10/2020.
//  Copyright © 2020 Nicolas Mondollot. All rights reserved.
//

import SwiftUI

struct DiscoverView: View {
    @Environment(\.openURL) var openURL

    @State var presentArea = false
    @State private var presentWebView = false

    @State private var popularRegions: [Region] = []
    @State private var regions: [Region] = []
    @State private var router = DiscoverRouter()

    @Environment(AppState.self) private var appState: AppState

    var body: some View {
        NavigationStack(path: $router.path) {
            GeometryReader { geo in
                ScrollView {
                    VStack(alignment: .leading) {

                        VStack {
                            HStack {
                                Button {
                                    presentWebView = true
                                } label: {

                                    VStack(alignment: .leading) {
                                        HStack {
                                            Text("discover.beginners_guide")
                                                .textCase(.uppercase)
                                        }
                                        .padding()
                                        .font(.subheadline.weight(.bold))
                                        .foregroundColor(Color.white)
                                        .frame(height: 70)
                                        .frame(maxWidth: .infinity)
                                        .background(
                                            LinearGradient(gradient:
                                                            Gradient(colors: [Color.green.opacity(0.4), Color.green.opacity(0.6)]),
                                                           startPoint: .top,
                                                           endPoint: .bottom)
                                        )
                                        .cornerRadius(8)
                                    }
                                }
                                .fullScreenCover(isPresented: $presentWebView) {
                                    SafariWebView(url: URL(string: "https://\(BrandConfig.Domains.www)/\(NSLocale.websiteLocale)/articles/beginners-guide")!)
                                        .ignoresSafeArea()

                                }

                                NavigationLink(value: DiscoverRoute.topAreasLevel) {

                                    VStack(alignment: .leading) {
                                        HStack {
                                            Image(systemName: "chart.bar")
                                            Text("discover.top_areas.level")
                                                .textCase(.uppercase)
                                        }
                                        .padding()
                                        .font(.subheadline.weight(.bold))
                                        .foregroundColor(Color.white)
                                        .frame(height: 70)
                                        .frame(maxWidth: .infinity)
                                        .background(
                                            LinearGradient(gradient:
                                                            Gradient(colors: [Color.blue.opacity(0.4), Color.blue.opacity(0.6)]),
                                                           startPoint: .top,
                                                           endPoint: .bottom)
                                        )
                                        .cornerRadius(8)
                                    }
                                }

                            }

                            HStack {
                                NavigationLink(value: DiscoverRoute.topAreasDryFast) {

                                    VStack(alignment: .leading) {
                                        HStack {
                                            Image(systemName: "sun.max")
                                            Text("discover.top_areas.dry_fast")
                                                .textCase(.uppercase)
                                        }
                                        .padding()
                                        .font(.subheadline.weight(.bold))
                                        .foregroundColor(Color.white)
                                        .frame(height: 70)
                                        .frame(maxWidth: .infinity)
                                        .background(
                                            LinearGradient(gradient:
                                                            Gradient(colors: [Color.yellow.opacity(0.4), Color.yellow.opacity(0.6)]),
                                                           startPoint: .top,
                                                           endPoint: .bottom)
                                        )
                                        .cornerRadius(8)
                                    }
                                }
                            }
                        }
                        .padding(.horizontal)
                        .padding(.top)
                    }

                    if popularRegions.isEmpty {
                        VStack {
                            Spacer()
                            HStack {
                                Spacer()
                                ProgressView()
                                Spacer()
                            }
                            Spacer()
                        }
                        .frame(minHeight: 200)
                    }
                    else {

                        VStack(alignment: .leading) {
                            Text("discover.popular")
                                .font(.title2).bold()
                                .padding(.top, 16)
                                .padding(.bottom, 8)
                                .padding(.horizontal)

                            VStack {
                                VStack(alignment: .leading) {

                                    ScrollView(.horizontal, showsIndicators: false) {
                                        HStack(alignment: .top, spacing: 0) {

                                            Color.white.opacity(0)
                                                .frame(width: 0, height: 1)
                                                .padding(.leading, 8)

                                            ForEach(popularRegions) { region in
                                                NavigationLink(value: DiscoverRoute.region(region.id)) {
                                                    RegionCardView(region: region, width: abs(geo.size.width-16*2-8)/2, height: abs(geo.size.width-16*2-8)/2*9/16)
                                                        .padding(.leading, 8)
                                                        .contentShape(Rectangle())
                                                }

                                            }

                                            Color.white.opacity(0)
                                                .frame(width: 0, height: 1)
                                                .padding(.trailing, 16)
                                        }
                                    }
                                }
                            }
                        }

                        VStack(alignment: .leading) {
                            HStack {
                                Text("discover.regions.all")
                                    .font(.title2.bold())

                                Spacer()

                            }

                            .padding(.top, 24)
                            .padding(.bottom, 8)
                            .padding(.horizontal)

                            VStack {
                                Divider()

                                ForEach(regions) { region in

                                    NavigationLink(value: DiscoverRoute.region(region.id)) {
                                        HStack {
                                            VStack(alignment: .leading, spacing: 6) {
                                                Text(region.name)
                                                    .frame(maxWidth: .infinity, alignment: .leading)
                                            }

                                            Spacer()

                                            Text(String(format: NSLocalizedString("discover.regions.clusters", comment: ""), region.clusters.count)).foregroundColor(Color(.systemGray))

                                            Image(systemName: "chevron.right")
                                                .font(.caption.weight(.bold))
                                                .foregroundColor(.gray.opacity(0.7))

                                        }
                                        .font(.body)
                                        .foregroundColor(.primary)
                                        .padding(.horizontal)
                                        .padding(.vertical, 4)
                                    }


                                    Divider().padding(.leading)
                                }
                            }
                        }

                        VStack(alignment: .leading) {
                            Text("discover.support")
                                .font(.title2).bold()
                                .padding(.top, 16)
                                .padding(.bottom, 8)
                                .padding(.horizontal)

                            VStack(alignment: .leading) {
                                Divider()

                                if let reviewURL = BrandConfig.AppStore.reviewURL {
                                    Button(action: {
                                        openURL(reviewURL)
                                    }, label: {
                                        HStack {
                                            Image(systemName: "star")
                                            Text("discover.rate")
                                            Spacer()
                                        }
                                        .font(.body)
                                        .foregroundColor(.primary)
                                    })

                                    Divider()
                                }

                                Button(action: {
                                    openURL(contributeURL)
                                }, label: {
                                    HStack {
                                        Image(systemName: "plus.app")
                                        Text("discover.contribute")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                })

                                Divider()

                                NavigationLink(value: DiscoverRoute.acknowledgements) {
                                    HStack {
                                        Image(systemName: "info.circle")
                                        Text("discover.acknowledgements")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                }

                                Divider()
                            }
                            .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity, alignment: .topLeading)
                            .padding(.horizontal)
                            .padding(.bottom)
                        }

#if DEVELOPMENT
                        VStack(alignment: .leading) {
                            Text("Dev")
                                .font(.title2).bold()
                                .padding(.top, 16)
                                .padding(.bottom, 8)
                                .padding(.horizontal)

                            VStack(alignment: .leading) {
                                Divider()

                                NavigationLink(value: DiscoverRoute.settings) {
                                    HStack {
                                        Image(systemName: "gearshape")
                                        Text("Settings")
                                        Spacer()
                                    }
                                    .font(.body)
                                    .foregroundColor(.primary)
                                }

                                Divider()
                            }
                            .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity, alignment: .topLeading)
                            .padding(.horizontal)
                            .padding(.bottom)
                        }
#endif
                    }
                }
                .navigationBarTitle(Text("discover.title"))
                .navigationDestination(for: DiscoverRoute.self) { route in
                    destination(for: route)
                }
                .task {
                    popularRegions = Region.all.filter{$0.popular}

                    regions = Region.all.sorted{
                        $0.name.folding(options: .diacriticInsensitive, locale: .current) < $1.name.folding(options: .diacriticInsensitive, locale: .current)
                    }
                }
            }
        }
        .environment(\.discoverRouter, router)
    }

    @ViewBuilder
    private func destination(for route: DiscoverRoute) -> some View {
        switch route {
        case .region(let id):
            if let region = Region.load(id: id) {
                RegionDetailView(region: region)
            }
        case .cluster(let id):
            if let cluster = Cluster.load(id: id) {
                ClusterDetailView(cluster: cluster)
            }
        case .area(let id):
            if let area = Area.load(id: id) {
                AreaView(area: area, linkToMap: true)
            }
        case .topAreasLevel:
            TopAreasLevelView()
        case .topAreasDryFast:
            TopAreasDryFast()
        case .topAreasBeginner:
            TopAreasBeginnerView()
        case .acknowledgements:
            AcknowledgementsView()
        case .settings:
            SettingsView()
        }
    }

    var contributeURL: URL {
        if(NSLocale.websiteLocale == "en") {
            return URL(string: "https://\(BrandConfig.Domains.www)/en/contribute")!
        }
        return URL(string: "https://\(BrandConfig.Domains.www)/de/contribute")!
    }
}

// FIXME: there is a weird bug when using StackNavigationViewStyle() on iPhone: the sheets get dismissed automatically the first time they are presented. Sometimes but not always. It seems to happen only when I try to present the sheet a couple of seconds after the app launch, which seems to indicate that the app is not properly loaded? maybe it's still setting up the navigationview "style"?? Anywa, I figured it's easier to just avoid using StackNavigationViewStyle() for now :)
// PLOT TWIST: https://stackoverflow.com/questions/62083810/swiftui-navigation-bar-items-going-haywire-when-swipe-back-fails
extension View {
    func phoneOnlyStackNavigationView() -> some View {
        if UIDevice.current.userInterfaceIdiom == .phone {
            return AnyView(self.navigationViewStyle(StackNavigationViewStyle()))
        } else {
            return AnyView(self)
        }
    }
}

